<?php
function send_exam_mail(string $to,string $subject,string $body): bool { $autoload=dirname(__DIR__).'/vendor/autoload.php'; if(!file_exists($autoload)){file_put_contents(__DIR__.'/mail-debug.log',date('c')." $to $subject $body\n",FILE_APPEND);return false;} require_once $autoload; try{$mail=new PHPMailer\PHPMailer\PHPMailer(true);$mail->isSMTP();$mail->Host='smtp.gmail.com';$mail->SMTPAuth=true;$mail->Username='your-gmail-address@gmail.com';$mail->Password='your-gmail-app-password';$mail->SMTPSecure=PHPMailer\PHPMailer\PHPMailer::ENCRYPTION_STARTTLS;$mail->Port=587;$mail->setFrom('your-gmail-address@gmail.com','Paper02C');$mail->addAddress($to);$mail->Subject=$subject;$mail->Body=$body;$mail->send();return true;}catch(Throwable $e){file_put_contents(__DIR__.'/mail-debug.log',$e->getMessage()."\n",FILE_APPEND);return false;}}
?>
